package com.nexusgroup.restaurant.service;

import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;

import com.nexusgroup.restaurant.aggregate.value.Dish;

import lombok.SneakyThrows;

/**
 * DO NOT EDIT THIS FILE
 */
public interface KitchenClient {

    Map<Dish, Integer> cookingTimes = Map.of(
        Dish.PANCAKES, 2000,
        Dish.CHICKEN, 10_000,
        Dish.ICE_CREAM, 1000,
        Dish.BEANS_ON_TOAST, 3000
    );

    @SneakyThrows(InterruptedException.class)
    static void cookDish(Dish dish) {
        final var failure = ThreadLocalRandom.current().nextInt(100) <= 20;

        if(failure) {
            throw new KitchenException("Simulated kitchen failure");
        }

        final var delay = cookingTimes.getOrDefault(dish, 4000);
        Thread.sleep(delay);
    }
}
